mapper.select:
SELECT so.approved_order_id, sr.outbound_request_id, sr.outbound_date, sr.approved_status, Pt.partner_name, Pd.product_name, M.member_name FROM OutboundOrder so INNER JOIN OutboundRequest sr ON so.outbound_request_id = sr.outbound_request_id INNER JOIN OutboundItem si ON sr.outbound_request_id = si.outbound_request_id INNER JOIN Product Pd ON si.product_id = Pd.product_id INNER JOIN Partner Pt ON Pd.partner_id = Pt.partner_id INNER JOIN Member M ON sr.member_id = M.member_id
AND sr.approved_status = #{searchValue}
AND M.member_name LIKE CONCAT('%', #{searchValue}, '%')
AND sr.member_id = #{searchValue}
AND 1=1
GROUP BY so.approved_order_id ORDER BY so.approved_order_id DESC

mapper.update:
UPDATE OutboundRequest
SET
approved_status = #{approvedStatus},
warehouse_id = #{warehouseId}
WHERE outbound_request_id = (
SELECT outbound_request_id
FROM OutboundOrder
WHERE approved_order_id = #{approvedOrderId}
)

mapper.select:
SELECT COUNT(*)
FROM Dispatch
WHERE approved_order_id = #{approvedOrderId}
